/// @brief One-way ANOVA with NA in every group, against summary(aov(y ~ g)).
TEST(RNaRemoval, OneWayAnova) {
    using Case = ref::NaOneWayAnova;
    const auto groups = MakeGroups(Case::kGroupsFlat, Case::kGroupsSizes, Case::kGroupsCount);
    const auto r = statcpp::one_way_anova(groups);
    EXPECT_R_FIELD(r.between.f_statistic, Case, kFStatistic);
    EXPECT_R_PVALUE(r.between.p_value, Case, kPValue);
    EXPECT_R_FIELD(r.between.df, Case, kDfBetween);
    EXPECT_R_FIELD(r.within.df, Case, kDfWithin);
    EXPECT_R_FIELD(r.between.ss, Case, kSsBetween);
    EXPECT_R_FIELD(r.within.ss, Case, kSsWithin);
}

/// @brief Kaplan-Meier estimator with NA times, against survfit.
TEST(RNaRemoval, KaplanMeier) {
    using Case = ref::NaKaplanMeier;
    const auto km = statcpp::kaplan_meier(AsVector(Case::kTimes), AsEvents(Case::kEvents));
    EXPECT_R_RANGE(km.times, Case, kEventTimes);
    EXPECT_R_RANGE(km.survival, Case, kSurvival);
}

// ============================================================================
// Propagation: descriptive statistics and correlation
// ============================================================================

/// @brief Descriptive statistics are NaN when the data contain NaN, as in R.
TEST(RNaPropagation, Descriptive) {
    using Case = ref::NaDescriptive;
    const auto x = AsVector(Case::kX);
    EXPECT_R_FIELD(statcpp::mean(x.begin(), x.end()), Case, kMean);
    EXPECT_R_FIELD(statcpp::sample_variance(x.begin(), x.end()), Case, kVariance);
    EXPECT_R_FIELD(statcpp::sample_stddev(x.begin(), x.end()), Case, kStddev);
    EXPECT_R_FIELD(statcpp::median(x.begin(), x.end()), Case, kMedian);
    EXPECT_R_FIELD(statcpp::range(x.begin(), x.end()), Case, kRange);
}

/// @brief Correlation coefficients are NaN when either input contains NaN, as in R's cor.
TEST(RNaPropagation, Correlation) {
    using Case = ref::NaCorrelation;
    const auto x = AsVector(Case::kX);
    const auto y = AsVector(Case::kY);
    EXPECT_R_FIELD(statcpp::pearson_correlation(x.begin(), x.end(), y.begin(), y.end()), Case, kPearson);
    EXPECT_R_FIELD(statcpp::spearman_correlation(x.begin(), x.end(), y.begin(), y.end()), Case, kSpearman);
    EXPECT_R_FIELD(statcpp::kendall_tau(x.begin(), x.end(), y.begin(), y.end()), Case, kKendall);
}

// ============================================================================
// Element-wise: adjustments, scaling and filters
// ============================================================================

/// @brief Multiplicity corrections count only the non-NaN p-values, as p.adjust does.
TEST(RNaElementwise, PAdjust) {
    using Case = ref::NaPAdjust;
    const auto p = AsVector(Case::kPValues);
    EXPECT_R_RANGE(statcpp::bonferroni_correction(p), Case, kBonferroni);
    EXPECT_R_RANGE(statcpp::holm_correction(p), Case, kHolm);
    EXPECT_R_RANGE(statcpp::benjamini_hochberg_correction(p), Case, kBh);
}

/// @brief standardize follows scale(): column statistics from the non-NaN values.
TEST(RNaElementwise, Scale) {
    using Case = ref::NaScale;
    const auto x = MakeMatrix(Case::kXFlat, Case::kXRows, Case::kXCols);
    const auto z = statcpp::standardize(x);
    EXPECT_R_RANGE(Flatten(z), Case, kScaledFlat);
}

/// @brief moving_average gives NaN only for the windows containing NaN, as stats::filter does.
TEST(RNaElementwise, MovingAverage) {
    using Case = ref::NaMovingAverage;
    const auto x = AsVector(Case::kX);
    const auto r = statcpp::moving_average(x.begin(), x.end(), Case::kWindow);
    EXPECT_R_RANGE(r, Case, kAverage);
}

// ============================================================================
// Distances: NaN coordinates skipped and the sum rescaled
// ============================================================================

/// @brief Lp distances follow dist(): NaN coordinates are skipped and the sum is rescaled.
TEST(RNaDistance, Dist) {
    using Case = ref::NaDistance;
    const auto a = AsVector(Case::kA);
    const auto b = AsVector(Case::kB);
    EXPECT_R_FIELD(statcpp::euclidean_distance(a.begin(), a.end(), b.begin(), b.end()), Case, kEuclidean);
    EXPECT_R_FIELD(statcpp::manhattan_distance(a.begin(), a.end(), b.begin(), b.end()), Case, kManhattan);
    EXPECT_R_FIELD(statcpp::minkowski_distance(a.begin(), a.end(), b.begin(), b.end(), Case::kP), Case,
                   kMinkowski);
    // The vector overloads in clustering.hpp follow the same rule.
    EXPECT_R_FIELD(statcpp::euclidean_distance(a, b), Case, kEuclidean);
    EXPECT_R_FIELD(statcpp::manhattan_distance(a, b), Case, kManhattan);
}

