/// @brief Simple regression with NA, against lm(y ~ x).
TEST(RNaModels, SimpleLinearRegression) {
    using Case = ref::NaSimpleLinearRegression;
    const auto x = AsVector(Case::kX);
    const auto y = AsVector(Case::kY);
    const auto m = statcpp::simple_linear_regression(x.begin(), x.end(), y.begin(), y.end());
    EXPECT_R_FIELD(m.intercept, Case, kIntercept);
    EXPECT_R_FIELD(m.slope, Case, kSlope);
    EXPECT_R_FIELD(m.r_squared, Case, kRSquared);
    EXPECT_R_FIELD(m.residual_se, Case, kResidualSe);
    EXPECT_R_FIELD(m.df_residual, Case, kDfResidual);
}

/// @brief Multiple regression with NA in X and y, against lm(y ~ X).
TEST(RNaModels, MultipleLinearRegression) {
    using Case = ref::NaMultipleLinearRegression;
    const auto X = MakeMatrix(Case::kXFlat, Case::kXRows, Case::kXCols);
    const auto y = AsVector(Case::kY);
    const auto m = statcpp::multiple_linear_regression(X, y);
    EXPECT_R_RANGE(m.coefficients, Case, kCoefficients);
    EXPECT_R_FIELD(m.r_squared, Case, kRSquared);
    EXPECT_R_FIELD(m.df_residual, Case, kDfResidual);
}

/// @brief Logistic regression with NA in x and y, against glm(family = binomial()).
TEST(RNaModels, LogisticRegression) {
    using Case = ref::NaLogisticRegression;
    const auto X = MakeMatrix(Case::kXFlat, Case::kXRows, Case::kXCols);
    const auto y = AsVector(Case::kY);
    const auto m = statcpp::logistic_regression(X, y);
    ASSERT_TRUE(m.converged);
    EXPECT_R_RANGE(m.coefficients, Case, kCoefficients);
    EXPECT_R_FIELD(m.residual_deviance, Case, kResidualDeviance);
    EXPECT_R_FIELD(m.df_residual, Case, kDfResidual);
}

