// ============================================================================
// Ordering and duplicates
// ============================================================================

/// @brief sort_values drops NaN, argsort places it last, rank_transform keeps it.
TEST(RNaOrdering, SortOrderRank) {
    using Case = ref::NaSortOrder;
    const auto x = AsVector(Case::kX);
    EXPECT_R_RANGE(statcpp::sort_values(x), Case, kSorted);
    EXPECT_R_RANGE(statcpp::sort_values(x, false), Case, kSortedDecreasing);
    EXPECT_R_RANGE(statcpp::rank_transform(x), Case, kRank);

    // Tied values may come in either order, so the comparison is on the values each
    // order selects; NaN positions must match exactly because NaN keeps its original order.
    auto selected = [&x](const std::vector<std::size_t>& order) {
        std::vector<double> out;
        for (const std::size_t i : order) out.push_back(x[i]);
        return out;
    };
    auto selected_ref = [&x](const double* order, std::size_t n) {
        std::vector<double> out;
        for (std::size_t k = 0; k < n; ++k) out.push_back(x[static_cast<std::size_t>(order[k])]);
        return out;
    };
    const auto asc = statcpp::argsort(x);
    const auto desc = statcpp::argsort(x, false);
    EXPECT_EQ(asc.size(), std::size(Case::kOrder));
    const auto asc_ref = selected_ref(Case::kOrder, std::size(Case::kOrder));
    const auto desc_ref = selected_ref(Case::kOrderDecreasing, std::size(Case::kOrderDecreasing));
    EXPECT_TRUE(statcpp_test::RCloseRange(selected(asc), asc_ref.data(), asc_ref.size(), Case::kRtol, Case::kAtol));
    EXPECT_TRUE(statcpp_test::RCloseRange(selected(desc), desc_ref.data(), desc_ref.size(), Case::kRtol, Case::kAtol));
    for (std::size_t k = asc.size() - 2; k < asc.size(); ++k) {
        EXPECT_EQ(static_cast<double>(asc[k]), Case::kOrder[k]);
        EXPECT_EQ(static_cast<double>(desc[k]), Case::kOrderDecreasing[k]);
    }
}

/// @brief drop_duplicates keeps one NaN, as unique does.
TEST(RNaOrdering, Unique) {
    using Case = ref::NaUnique;
    EXPECT_R_RANGE(statcpp::drop_duplicates(AsVector(Case::kX)), Case, kUnique);
}

